.wc-live-transfer .wc-science-story {margin:0 0 14px;padding:13px;border:1px solid var(--lt-line);border-radius:13px;background:var(--lt-card);color:var(--lt-ink)}
.wc-live-transfer .wc-science-story-title {font-size:14px;line-height:1.5;color:var(--lt-ink);margin-bottom:10px;display:block}
.wc-live-transfer .wc-science-story-chain {display:grid;grid-template-columns:1fr;gap:8px;align-items:stretch}
.wc-live-transfer .wc-science-story-step {padding:10px 12px;background:var(--lt-paper);border:1px solid var(--lt-line);border-radius:10px;min-width:0}
.wc-live-transfer .wc-science-story-step>span {display:block;font-size:13px;line-height:1.5;color:var(--lt-muted);margin-bottom:4px}
.wc-live-transfer .wc-science-story-step>strong {display:block;font-size:14px;line-height:1.6;color:var(--lt-ink)}
