.wc-live-transfer .wc-matter-energy-grid dd strong {font-size:15px;line-height:1.5;color:var(--lt-ink)}
.wc-live-transfer .wc-matter-energy-grid dd>span {display:block;margin-top:6px;font-size:14px;line-height:1.6;color:var(--lt-muted)}
