.wc-lt-water-path {display:grid;grid-template-columns:1fr;gap:10px;align-items:center;min-width:0}
.wc-lt-water-node {display:flex;gap:12px;align-items:center;padding:12px;border:1px solid var(--lt-line);border-radius:12px;background:var(--lt-paper);min-width:0}
.wc-lt-water-node>div {display:grid;gap:4px;min-width:0}
.wc-lt-node-role {font-size:13px;line-height:1.4;color:var(--lt-muted)}
