.wc-lt-node-phase {font-size:14px;line-height:1.5;color:var(--lt-muted)}
.wc-lt-water-symbol {flex:0 0 56px;width:56px;height:56px;overflow:visible}
.wc-lt-drop {stroke:var(--lt-water);fill:var(--lt-water-fill);stroke-width:2.3;stroke-linejoin:round}
.wc-lt-ice {stroke:var(--lt-water);fill:none;stroke-width:2.3;stroke-linecap:round;stroke-linejoin:round}
.wc-lt-vapor {stroke:var(--lt-water);fill:var(--lt-card);stroke-width:2}
.wc-lt-water-connector {display:grid;justify-items:center;gap:4px;font-size:13px;line-height:1.5;color:var(--lt-muted)}
