.wc-lt-heat-arrow svg {width:56px;height:28px;transform:rotate(90deg);margin:8px 0}
.wc-lt-heat-arrow path {stroke:var(--lt-heat)}
.wc-live-transfer .wc-lt-no-latent,.wc-live-transfer .wc-lt-heat-reading {font-size:14px;line-height:1.6;color:var(--lt-ink);margin:8px 0 0}
.wc-live-transfer .wc-lt-no-latent {padding:10px;border:1px dashed var(--lt-line);border-radius:10px;background:var(--lt-paper)}
.wc-live-data.wc-data-view {container:live-data / inline-size;background:var(--lt-paper);color:var(--lt-ink);border-color:var(--lt-line)}
.wc-live-data .wc-data-summary {min-height:48px;padding:12px;font-size:15px;line-height:1.5;color:var(--lt-ink)}
