.wc-live-data .wc-data-table th,.wc-live-data .wc-data-table td {padding:12px;vertical-align:top;border-color:var(--lt-line);color:var(--lt-ink);font-size:14px;line-height:1.6;overflow-wrap:anywhere}
.wc-live-data .wc-data-table th {width:29%;font-size:13px;color:var(--lt-muted);background:var(--lt-paper)}
.wc-live-data .wc-data-table strong {font-size:14px;line-height:1.6;color:var(--lt-ink)}
.wc-live-data .wc-data-table td>span {display:block;font-size:13px;line-height:1.6;color:var(--lt-muted);margin-top:5px}
.wc-live-data summary:focus-visible {outline:3px solid var(--lt-focus);outline-offset:3px}
@container live-transfer (min-width:620px) {
  .wc-lt-water-path {grid-template-columns:minmax(0,1fr) 64px minmax(0,1fr)}
